import{_ as s,h as r,i as e,c as i,v as o,p as n,x as t,m as p,e as c,S as C}from"./chunks/framework.Dvtg8yj2.js";const _=JSON.parse('{"title":"Celestica 板卡与机柜系统化","description":"","frontmatter":{"title":"Celestica 板卡与机柜系统化","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/jalapeno-celestica.md","filePath":"llm/jalapeno-celestica.md","lastUpdated":1788454257000}'),d={name:"llm/jalapeno-celestica.md"};function h(A,a,B,E,m,u){const l=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="celestica-板卡与机柜系统化" tabindex="-1">Celestica 板卡与机柜系统化 <a class="header-anchor" href="#celestica-板卡与机柜系统化" aria-label="Permalink to &quot;Celestica 板卡与机柜系统化&quot;">​</a></h1><div class="epigraph"><p>Jalapeño 是多代计算平台的第一步：OpenAI 设计加速器，Broadcom 做硅实施与网络，Celestica 贡献板卡、机柜与系统专长。</p><footer>—— OpenAI 与 Broadcom 联合公布的平台分工</footer></div><p>芯片能算，不等于机房能装。Jalapeño 封装是 700 W 级 HBM4 近存器件，还要配主机、铜缆背板、Tomahawk 交换、液冷与供电，才能变成可复制的 128 芯片本地域。OpenAI 把这条工业化路径明确写成与 <strong>Celestica</strong> 合作：板卡、机柜、系统集成、可规模生产的整机。Hot Chips 2026 把产品说成硅加「主机与加速器机柜对」，并向 Broadcom 与 Celestica 致谢。本篇写系统化要回答的工程问题——托盘怎么切、主机怎么绑、故障域怎么划——不编造 Celestica 未公布的料号、线缆芯数或机柜 SKU 功耗上限。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自研 ASIC 项目常见的断裂发生在 GDS 之后：实验室插座上跑通的工程样品，到不了能上架、能维护、能过安全认证的机柜。板卡要处理 HBM4 封装的电源完整性与 700 W 热密度；机柜要把 128 颗装置、交换、背板收成一个本地域；主机侧要提供 PCIe / CXL 一类的控制与数据入口，又不能成为集合通信的瓶颈。这些不是算法组的内核问题，却决定 <a href="/llm/jalapeno-sliced-hbm">切片化</a> 与 <a href="/llm/jalapeno-tomahawk">Tomahawk 域</a> 在墙上钟里是否存在。</p><p>OpenAI 选择把「从芯片到可部署系统」交给有规模制造与整机经验的合作方，而不是把第一代平台做成仅内部实验室可复制的架子。Celestica 在公开表述里的角色是 <strong>board, rack, and system</strong>：把 Broadcom 实施的硅、Tomahawk 交换、以及 OpenAI 的加速器架构收成工厂能重复的单元。没有这一层，九个月的 RTL 到 tapeout 只产生晶圆，不产生 InferenceX 曲线上的机柜。</p><h3 id="主机柜与加速柜成对-而不是一张万能主板" tabindex="-1">主机柜与加速柜成对，而不是一张万能主板 <a class="header-anchor" href="#主机柜与加速柜成对-而不是一张万能主板" aria-label="Permalink to &quot;主机柜与加速柜成对，而不是一张万能主板&quot;">​</a></h3><p>Hot Chips 把形态写成主机与加速器机柜成对。含义是：CPU、DRAM、前端网、本地盘在主机侧；Jalapeño、HBM4、加速器域交换在加速侧。成对设计让两种热密度、两种布线（前端以太 vs 背板 Clos）分开，也让升级可以换加速柜而不必同步换完所有通用服务器。具体托盘如何命名、每托盘几颗 ASIC，官方演讲没有写成可引用的装配图；128 颗本地域是系统级事实，装配切分以厂商后续硬件手册为准。</p><p><span class="marginnote">第三方机柜拆解常会给出托盘绰号与每槽芯片数。那是分析，不是 OpenAI 数据手册。规划本地域容量时用 128 颗与 700 W 封装、216 GiB/颗这些已公布数字，用机柜功率=128×700 W 量级做<strong>下限量级</strong>时仍要加上交换、主机、泵与转换损耗，不能把 89.6 kW 当成整柜铭牌。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>系统化按三个可替换单元来做。<strong>板卡</strong>：加速器模组承载封装、VRM、水冷冷板、到背板的高速连接器；主机板卡承载 CPU 与前端 I/O。<strong>托盘</strong>：把若干板卡收成可维护的 1U/2U 级现场可替换单元，液冷歧管与电源连接按托盘盲插。<strong>机柜</strong>：计算托盘加交换托盘加冷量分配，背板把 128 颗收成本地域，柜间光纤/铜缆把最多 16 柜收成 2048 全局域。Celestica 的工作是让这三层的机械、热、电、制造公差同时收敛，并且能在代工线上重复，而不是只做一台展厅样机。</p><p>运维接口应暴露「本柜 128 域」与「全局 2048 域」为拓扑标签，调度器按域绑 TP / EP，见 <a href="/llm/scale-up-vs-scale-out">scale-up vs scale-out</a>。现场更换的粒度是托盘或机柜，不是焊在中介层上的 HBM 立方体。固件、CPLD、水冷泄漏检测属于系统包，必须与 CAN 总线或等效机柜管理成套交付，否则芯片团队会在机房里重新发明 BMC。</p>',12)),(e(),n(C,null,{default:t(()=>[c(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20PAIR%5B%22%E4%B8%BB%E6%9C%BA%E6%9F%9C%20%2B%20%E5%8A%A0%E9%80%9F%E6%9F%9C%E6%88%90%E5%AF%B9%22%5D%0A%20%20%20%20HOST%5B%22%E4%B8%BB%E6%9C%BA%EF%BC%9ACPU%20%C2%B7%20DRAM%20%C2%B7%20%E5%89%8D%E7%AB%AF%E7%BD%91%22%5D%0A%20%20%20%20ACC%5B%22%E5%8A%A0%E9%80%9F%EF%BC%9AJalape%C3%B1o%20%E6%9D%BF%E5%8D%A1%20%C2%B7%20%E4%BA%A4%E6%8D%A2%E6%89%98%E7%9B%98%20%C2%B7%20%E8%83%8C%E6%9D%BF%22%5D%0A%20%20%20%20HOST%20---%20%7C%22%E6%8E%A7%E5%88%B6%E4%B8%8E%E5%9D%97%E6%95%B0%E6%8D%AE%22%7C%20ACC%0A%20%20end%0A%20%20ACC%20--%3E%20LOCAL%5B%22%E6%9C%AC%E5%9C%B0%E5%9F%9F%20128%22%5D%0A%20%20LOCAL%20--%3E%20GLOB%5B%22%E5%85%A8%E5%B1%80%E5%9F%9F%202048%22%5D%0A%20%20CEL%5B%22Celestica%EF%BC%9A%E6%9D%BF%E5%8D%A1%20%2F%20%E6%9C%BA%E6%9F%9C%20%2F%20%E7%B3%BB%E7%BB%9F%22%5D%20--%3E%20PAIR%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="制造与认证是架构的一部分" tabindex="-1">制造与认证是架构的一部分 <a class="header-anchor" href="#制造与认证是架构的一部分" aria-label="Permalink to &quot;制造与认证是架构的一部分&quot;">​</a></h3><p>可规模生产意味着：连接器插拔寿命、线缆长度档位、冷板与封装的机械耦合、泄漏与冷凝、安规与电磁兼容。这些项目失败时，表现是「偶发 NCCL 超时」或「某条 Clos 链路 CRC」，看起来像网络栈，根因在系统。把 Celestica 写进平台声明，是承认第一代 Jalapeño 的交付物是<strong>机柜</strong>，不是芯片样品。OpenAI 说工程样品已在实验室按生产目标频率与功耗跑工作负载（含 GPT-5.3-Codex-Spark），那是硅与板卡的联合里程碑；初始部署目标写在 2026 年底，那是整机与机房的里程碑。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>700 W 封装的热必须在板卡级被冷板接走，再在机柜级被 CDU 接走。近存 HBM4 立方体对温度敏感，系统化若只给逻辑裸片做好冷却、内存侧热点，会先丢带宽再丢数据。电源从母线到封装要经过多级转换，效率点决定机柜进线功率；「芯片 700 W」与「机柜每槽 1 kW+」之间的空隙由系统吃掉。</p><p>电学上，背板是本地域的物理实现：短距铜把 ASIC 连到 Tomahawk 托盘。系统厂商的价值是控制插入损耗与 skew，使 SerDes 工作在以太 Scale-Up 需要的误码率上。这与 Broadcom 宣称 Tomahawk 6 对无源铜缆有较长可达距离是同一条供应链故事：交换硅提供 SerDes，整机提供通道。</p><p><span class="marginnote">OpenAI 用 Pareto 前沿比较的是<strong>系统</strong>在封装 TDP 归一化下的吞吐与延迟，Jalapeño 按 700 W、对照 GPU 按 1.2–1.4 kW。没有 Celestica 这一层把封装 TDP 变成可上架功耗，这些点无法落在同一张图上。</span></p><h3 id="故障、备件与爆炸半径" tabindex="-1">故障、备件与爆炸半径 <a class="header-anchor" href="#故障、备件与爆炸半径" aria-label="Permalink to &quot;故障、备件与爆炸半径&quot;">​</a></h3><p>本地域 128 颗共享背板与交换托盘，故障半径是机柜，不是单卡。备件策略应按托盘与整柜，液冷快接头与电源架是柜级 SKU。全局域 2048 把爆炸半径再放大到 16 柜：Clos 脊或柜间光模块故障会切掉 EP 组。系统手册必须写清：哪些链路冗余、哪些只能降域运行。不要用通用 x86 机柜的热插 GPU 流程套到焊死在 2.5D 封装上的加速器。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 Celestica 写成芯片设计者。架构与 RTL 在 OpenAI，硅实施与 Tomahawk 在 Broadcom，整机在 Celestica。不要填写未公开的机柜 U 数、托盘配比、CPU 型号与 PCIe 分叉。不要假设第一代平台对外销售给任意云——公开材料把它定位为 OpenAI 自用推理平台的多代中的第一代，部署与 Microsoft 等伙伴的机房规划绑定。</p><p>成本账里，系统化占比很高：冷量、交换、铜缆、认证往往不比晶圆便宜。评测「每美元 token」若只算 ASIC 晶圆，会系统性低估。反过来，把某一代机柜的代工报价当成长期定律也会过期。</p><p><span class="marginnote">出处：OpenAI–Broadcom 联合稿中的 Celestica 分工（board, rack, system）；Hot Chips 2026 的主机/加速柜对与致谢。不引用未公开装配图与料号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Celestica 承担 Jalapeño 从封装到可复制机柜的板卡、机柜与系统集成。</li><li>公开形态是主机柜与加速柜成对；本地域 128 颗是系统级单元。</li><li>700 W HBM4 封装的热、电、机械必须在托盘级收敛，否则实验室频率到不了机房。</li><li>故障域按托盘/机柜/2048 域划分，不能按单卡热插假设。</li><li>评测与调度都应对着机柜域，而不是对着裸芯片。</li><li>出处：OpenAI / Broadcom 公开平台说明；Hot Chips 2026。</li></ul>',14))])}const D=s(d,[["render",h]]);export{_ as __pageData,D as default};
